pub struct Pagination {
    pub page: usize,
    pub per_page: usize,
}

pub fn list_items(p: Pagination) -> Vec<String> {
    let all = (1..=100).map(|i| format!("item-{}", i)).collect::<Vec<_>>();
    let start = p.page.saturating_sub(1) * p.per_page;
    let end = start + p.per_page;
    all.get(start..end).unwrap_or(&[]).to_vec()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn t_default() {
        let p = Pagination { page: 1, per_page: 10 };
        assert_eq!(list_items(p).len(), 10);
    }

    #[test]
    fn t_page10() {
        let p = Pagination { page: 10, per_page: 10 };
        assert_eq!(list_items(p).len(), 10);
        assert_eq!(list_items(Pagination { page: 10, per_page: 10 })[0], "item-91");
    }

    #[test]
    fn t_custom_per_page() {
        let p = Pagination { page: 1, per_page: 5 };
        assert_eq!(list_items(p).len(), 5);
        assert_eq!(list_items(Pagination { page: 3, per_page: 5 })[0], "item-11");
    }

    #[test]
    fn t_out_of_range() {
        let p = Pagination { page: 100, per_page: 10 };
        assert!(list_items(p).is_empty());
    }

    #[test]
    fn t_page_zero() {
        let p = Pagination { page: 0, per_page: 10 };
        assert_eq!(list_items(p).len(), 10);
        assert_eq!(list_items(Pagination { page: 0, per_page: 10 })[0], "item-1");
    }
}
